import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.yGqRar0R.js";const u=JSON.parse('{"title":"vSLS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/vsls/index.md","filePath":"guide/vsls/index.md"}'),r={name:"guide/vsls/index.md"};function i(o,e,l,d,c,m){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="vsls" tabindex="-1">vSLS <a class="header-anchor" href="#vsls" aria-label="Permalink to &quot;vSLS&quot;">​</a></h1><p><strong>vSLS</strong> is a <a href="https://docs.papermc.io/velocity" target="_blank" rel="noreferrer">Velocity</a> plugin that lets you create and manage SLS servers from in-game commands. Allowing you to control and interact with your infrastructure directly from Minecraft.</p><p>Source and build instructions: <a href="https://github.com/jessefaler/SLS/tree/main/vsls" target="_blank" rel="noreferrer">SLS <code>vsls</code> on GitHub</a>.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Create and manage server instances</li><li>Browse and inspect blueprints</li><li>Monitor active servers and detailed instance info</li><li>Manage nodes</li><li>Simple matchmaking system: automatically creates servers when players queue for a blueprint via the join command</li></ul><p>See <strong><a href="./installation.html">Installing vSLS</a></strong> for requirements, download, and first-time configuration.</p><p><strong><a href="./configuring.html">Configuring vSLS</a></strong> documents <code>plugins/vsls/config.yml</code> and blueprint <strong><code>annotations.vsls</code></strong>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Many administrative commands require:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sls.command.admin</span></span></code></pre></div><p>To give this permission to players you will need a permissions plugin I recommend <a href="https://luckperms.net/download" target="_blank" rel="noreferrer">LuckPerms</a>.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Command documentation: <strong><a href="./commands.html">vSLS commands</a></strong>.</p>',13)])])}const h=a(r,[["render",i]]);export{u as __pageData,h as default};
